module TopModule (
    input  x3,
    input  x2,
    input  x1,
    output f
);
    assign f = (~x3 & x2) | (x3 & x1);
endmodule

module tb;
    reg x3, x2, x1;
    wire f;

    TopModule uut (
        .x3(x3),
        .x2(x2),
        .x1(x1),
        .f(f)
    );

    // Independent model
    function ref_f(input reg X3, X2, X1);
        case ({X3, X2, X1})
            3'b000: ref_f = 0;
            3'b001: ref_f = 0;
            3'b010: ref_f = 1;
            3'b011: ref_f = 1;
            3'b100: ref_f = 0;
            3'b101: ref_f = 1;
            3'b110: ref_f = 0;
            3'b111: ref_f = 1;
            default: ref_f = 0;
        endcase
    endfunction

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            {x3, x2, x1} = i[2:0];
            #10;
            if (f !== ref_f(x3, x2, x1)) begin
                $display("SELFTEST FAIL: mismatch at x3=%b x2=%b x1=%b: got %b, expected %b",
                         x3, x2, x1, f, ref_f(x3, x2, x1));
                $finish;
            end
        end
        $display("SELFTEST PASS");
        $finish;
    end
endmodule
